import type { Metadata } from "next";

export const SITE_NAME = "زغاليل";
export const DEFAULT_TITLE = "زغاليل | أول عالم كرتوني مصري متكامل";
export const DEFAULT_DESCRIPTION =
  "شخصيات كرتونية مصرية تصنع محتوى ترفيهي آمن وممتع لكل أفراد العائلة. من سن 7 لـ 77 سنة. حلقات، أغاني، دكان، وعروض مسرحية.";

/**
 * Title, description, canonical URL and social preview (Open Graph + X card) for a page.
 * Images live in public/og and are generated by `npm run og`.
 */
export function pageMeta({
  title,
  description,
  path,
  image,
}: {
  title?: string;
  description: string;
  path: string;
  image: string;
}): Metadata {
  const full = title ? `${title} | ${SITE_NAME}` : DEFAULT_TITLE;
  const images = [{ url: image, width: 1200, height: 630, alt: full, type: "image/png" }];
  return {
    ...(title ? { title } : {}),
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "ar_EG",
      siteName: SITE_NAME,
      title: full,
      description,
      url: path,
      images,
    },
    twitter: { card: "summary_large_image", title: full, description, images: [image] },
  };
}
